/* Neural inference stays off the game/animation thread. Assets are self-hosted. */
if(typeof ort==='undefined')importScripts('ort.wasm.min.js','phonemes.js?v=vault-theatre-5','character.js?v=grit-2');
let session,initializing,latest=0,pending=null,running=false;
async function initialize(config){ort.env.wasm.numThreads=1;ort.env.wasm.proxy=false;ort.env.wasm.wasmPaths={mjs:config.glueURL,wasm:config.wasmURL};if(config.wasm)ort.env.wasm.wasmBinary=new Uint8Array(config.wasm);else if(config.wasmParts){const parts=await Promise.all(config.wasmParts.map(async url=>{const response=await fetch(url);if(!response.ok)throw Error('Voice runtime download failed');return new Uint8Array(await response.arrayBuffer())}));const joined=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let at=0;for(const part of parts){joined.set(part,at);at+=part.length}ort.env.wasm.wasmBinary=joined}const bytes=config.model?new Uint8Array(config.model):new Uint8Array(await(await fetch(config.modelURL)).arrayBuffer());session=await ort.InferenceSession.create(bytes,{executionProviders:['wasm'],graphOptimizationLevel:'all'});postMessage({type:'ready'})}
async function renderPart(text,speed){const {phoneIds,toneIds,langIds}=textToPhonemeIds(text),n=phoneIds.length;const i64=a=>new ort.Tensor('int64',BigInt64Array.from(a,BigInt),[1,a.length]);const feeds={x:i64(phoneIds),x_lengths:new ort.Tensor('int64',BigInt64Array.of(BigInt(n)),[1]),sid:new ort.Tensor('int64',BigInt64Array.of(0n),[1]),tone:i64(toneIds),language:i64(langIds),bert:new ort.Tensor('float32',new Float32Array(n*1024),[1,1024,n]),ja_bert:new ort.Tensor('float32',new Float32Array(n*768),[1,768,n]),noise_scale:new ort.Tensor('float32',Float32Array.of(.35),[1]),noise_scale_w:new ort.Tensor('float32',Float32Array.of(.5),[1]),length_scale:new ort.Tensor('float32',Float32Array.of(1/speed),[1])};const result=await session.run(feeds);return shapeHouseVoice(result.audio.data)}
async function pump(){if(running)return;running=true;try{await initializing;while(pending){const job=pending;pending=null;if(job.id!==latest)continue;try{const pieces=[];let size=0;for(const sentence of job.parts){const words=sentence.split(/\s+/),chunks=[];for(let i=0;i<words.length;i+=28)chunks.push(words.slice(i,i+28).join(' '));for(const chunk of chunks){if(job.id!==latest)break;const pcm=await renderPart(chunk,job.delivery.speed);pieces.push(pcm);size+=pcm.length}if(job.id!==latest)break;const pause=new Float32Array(Math.round(44100*job.delivery.pause/1000));pieces.push(pause);size+=pause.length}if(job.id!==latest)continue;const pcm=new Float32Array(size);let offset=0;for(const piece of pieces){pcm.set(piece,offset);offset+=piece.length}postMessage({type:'clip',id:job.id,pcm:pcm.buffer,sampleRate:44100},[pcm.buffer])}catch(error){if(job.id===latest)postMessage({type:'error',id:job.id,message:'The House could not render that transmission.'})}}}catch(error){postMessage({type:'failed',message:'The House voice could not load.'})}finally{running=false;if(pending)pump()}}
self.onmessage=event=>{const message=event.data;if(message.type==='init'){initializing=initialize(message).catch(error=>{postMessage({type:'failed',message:'The House voice could not load.'});throw error});initializing.catch(()=>{});return}if(message.type==='cancel'){latest=message.id;pending=null;return}if(message.type==='render'){latest=message.id;pending=message;pump()}};
